# Define Graph Layer Types

TypeScript types for all graph layer operations.

## Deliverables

### `src/graph/types.ts`

```typescript
// === Node Input Types ===

interface CreateNodeInput {
  type: 'spec' | 'issue' | 'feedback' | 'external'
  title: string
  content?: string
  priority?: number
  tags?: string[]
  parent_id?: string

  // Issue-specific
  status?: string
  assignee?: string

  // Feedback-specific
  target_id?: string
  target_anchor?: Anchor
  feedback_type?: 'comment' | 'suggestion' | 'request'

  // External-specific
  uri?: string
  source?: string

  metadata?: Record<string, unknown>
}

interface UpdateNodeInput {
  title?: string
  content?: string
  priority?: number
  status?: string
  assignee?: string
  archived?: boolean
  resolved?: boolean
  dismissed?: boolean
  metadata?: Record<string, unknown>
}

interface DeleteOptions {
  hard?: boolean  // Default: false (soft delete/archive)
}

// === Edge Input Types ===

interface CreateEdgeInput {
  from_id: string
  to_id: string
  type: EdgeType
  metadata?: Record<string, unknown>
}

// === Filter Types ===

interface NodeFilter {
  type?: NodeType | NodeType[]
  status?: string | string[]
  tags?: string[]
  parent_id?: string
  archived?: boolean | null
  search?: string
  priority?: number | { min?: number; max?: number }
  assignee?: string
  limit?: number
  offset?: number
  orderBy?: 'created_at' | 'updated_at' | 'priority' | 'title'
  orderDirection?: 'asc' | 'desc'
}

interface EdgeFilter {
  type?: EdgeType | EdgeType[]
  from_id?: string
  to_id?: string
  limit?: number
  offset?: number
}

// === Query Option Types ===

interface BlockerOptions {
  transitive?: boolean
  activeOnly?: boolean
  maxDepth?: number
}

interface ReadyOptions {
  type?: 'issue' | 'spec'
  tags?: string[]
  priority?: number | { min?: number; max?: number }
  assignee?: string
  limit?: number
}

interface FeedbackOptions {
  type?: 'comment' | 'suggestion' | 'request'
  resolved?: boolean
  includeDismissed?: boolean
}

// === Validation Types ===

interface ValidationResult {
  valid: boolean
  errors: ValidationError[]
  warnings: ValidationWarning[]
}

interface ValidationError {
  code: string
  field?: string
  message: string
}

interface ValidationWarning {
  code: string
  field?: string
  message: string
}

interface CycleResult {
  hasCycle: boolean
  cycle?: string[]
}

// === Store Config ===

interface GraphStoreConfig {
  basePath: string
  autoInit?: boolean
  flush?: {
    debounceMs?: number
    maxDelayMs?: number
  }
}
```

## Acceptance Criteria

- [ ] All input types defined with JSDoc comments
- [ ] All filter types support the queries from INTERFACE.md
- [ ] Validation types support errors and warnings
- [ ] Config types have sensible defaults documented
- [ ] Types exported from `src/graph/index.ts`

