# Implement QueryEngine

Query capabilities for graph traversal and filtering.

## Deliverables

### `src/graph/query.ts`

```typescript
interface QueryEngine {
  // === Basic Queries ===
  nodes(filter: NodeFilter): Promise<Node[]>
  edges(filter: EdgeFilter): Promise<Edge[]>

  // === Relationship Queries ===
  edgesFrom(nodeId: string, type?: EdgeType): Promise<Edge[]>
  edgesTo(nodeId: string, type?: EdgeType): Promise<Edge[]>
  edgesFor(nodeId: string, type?: EdgeType): Promise<Edge[]>

  // === Dependency Queries ===
  blockers(nodeId: string, options?: BlockerOptions): Promise<Node[]>
  blocking(nodeId: string, options?: BlockerOptions): Promise<Node[]>
  isBlocking(fromId: string, toId: string): Promise<boolean>

  // === Spec/Issue Queries ===
  implementers(specId: string): Promise<Issue[]>
  specs(issueId: string): Promise<Spec[]>

  // === Hierarchy Queries ===
  children(nodeId: string): Promise<Node[]>
  parent(nodeId: string): Promise<Node | null>
  ancestors(nodeId: string): Promise<Node[]>
  descendants(nodeId: string): Promise<Node[]>

  // === Ready Query ===
  ready(options?: ReadyOptions): Promise<Issue[]>

  // === Feedback Queries ===
  feedback(targetId: string, options?: FeedbackOptions): Promise<Feedback[]>
  unresolvedFeedback(targetId?: string): Promise<Feedback[]>
}

// Factory
function createQueryEngine(storage: Storage): QueryEngine
```

## Implementation Details

### Ready Computation (Application Code)

```typescript
async function ready(options?: ReadyOptions): Promise<Issue[]> {
  // 1. Get all open, non-archived issues
  const issues = await storage.queryNodes({
    type: 'issue',
    status: 'open',
    archived: false,
    ...options
  })

  // 2. For each issue, check if it has active blockers
  const readyIssues: Issue[] = []

  for (const issue of issues) {
    const blockerEdges = await storage.getEdgesTo(issue.id, 'blocks')

    // Check if any blocker is active (not closed, not archived)
    let hasActiveBlocker = false
    for (const edge of blockerEdges) {
      const blocker = await storage.getNode(edge.from_id)
      if (blocker && !blocker.archived && blocker.status !== 'closed') {
        hasActiveBlocker = true
        break
      }
    }

    if (!hasActiveBlocker) {
      readyIssues.push(parseNode(issue) as Issue)
    }
  }

  return readyIssues
}
```

### Transitive Blockers

```typescript
async function blockers(
  nodeId: string, 
  options?: BlockerOptions
): Promise<Node[]> {
  const result: Node[] = []
  const visited = new Set<string>()
  const maxDepth = options?.maxDepth ?? 10

  async function collect(id: string, depth: number): Promise<void> {
    if (depth > maxDepth || visited.has(id)) return
    visited.add(id)

    const edges = await storage.getEdgesTo(id, 'blocks')

    for (const edge of edges) {
      const blocker = await storage.getNode(edge.from_id)
      if (!blocker) continue

      // Filter by activeOnly
      if (options?.activeOnly) {
        if (blocker.archived || blocker.status === 'closed') continue
      }

      result.push(parseNode(blocker))

      // Recurse for transitive
      if (options?.transitive) {
        await collect(edge.from_id, depth + 1)
      }
    }
  }

  await collect(nodeId, 0)
  return result
}
```

## Acceptance Criteria

- [ ] All query methods from interface implemented
- [ ] `ready()` computes in application code (not SQL view)
- [ ] `blockers()`/`blocking()` support transitive option
- [ ] Hierarchy queries work with `parent_id` field
- [ ] Feedback queries filter by resolved/dismissed
- [ ] Proper type narrowing (returns `Issue[]` not `Node[]` where appropriate)

